// GENERATED by scripts/fetch-site-photos.py. Do not edit by hand.
//
// Freely licensed photographs from Wikimedia Commons, used as stand-ins for
// sites nobody has photographed. None of them is any of these sites, and
// every surface that shows one says so.
//
// Sourced from Commons *categories* rather than free-text search. Search was
// tried first and was far too loose: a query for brick apartment buildings
// returned bronze age rings on a measuring scale, and one for RVs returned
// empty Welsh fields. Categories are curated by hand, and the California and
// Bay Area ones keep the pictures in roughly the right place.
//
// Attribution is a licence condition for most of these, not a courtesy: the
// author, the licence and the source page travel with every image and are
// rendered under it.

export type SitePhoto = {
  src: string
  alt: string
  /** Author, as Commons records them. */
  author: string
  /** Licence short name, e.g. "CC BY-SA 4.0". */
  licence: string
  /** The file's page on Commons, which carries the full licence terms. */
  source: string
}

